/// <summary>
///  AVA/WEN 2024/04/12    AVA_011738_PresetAllocations
/// </summary>
/// <param name = "_ruleId">LedgerAllocationRuleID</param>
public static void avaInitFromParm(LedgerAllocationRuleID _ruleId)
{
    AVAFPLLedgerAllocationRuleOperationsTax     oprTax, defaultValues;
    const str DefaultRule = 'Default';
    RecordInsertList    insList = new RecordInsertList(tableNum(AVAFPLLedgerAllocationRuleOperationsTax));

    if (_ruleId)
    {
        select firstonly oprTax where oprTax.RuleId == _ruleId;
        if (!oprTax)
        {
            while select defaultValues where defaultValues.RuleId == DefaultRule
            {
                oprTax.selectForUpdate(true);
                oprTax.RuleId = _ruleId;
                oprTax.CurrentOperationsTax = defaultValues.CurrentOperationsTax;
                insList.add(oprTax);
            }
            insList.insertDatabase();
        }
    }
}
